import sys; sys.path.insert(0, '/workspace/cur/tb'); from tbw import *
WRITE('phytophotodermatitis',
 ["A **non-immune phototoxic** reaction: plant **furocoumarins** (psoralens) on the skin plus **UVA** light.",
  "Anyone can be affected with enough sap and sun; no previous sensitisation is needed.",
  "Burning redness and **blisters** appear about **24 h** after exposure and peak at **48–72 h**, in **streaks, drips or hand-prints**.",
  "**Hyperpigmentation** follows and can last months to years; it is often why people present.",
  "Manage like a superficial burn: wash sap off, keep out of sun for 48 h, short topical steroid, strict sun protection. Think **safeguarding** with odd marks in children."],
 [
 S('overview', 'Overview',
   "Phytophotodermatitis is a **phototoxic** skin reaction that happens when light-sensitising chemicals in some plants (**furocoumarins**, also called psoralens) get on the skin and are then exposed to **ultraviolet A (UVA)**. It is not an allergy: the sap and light damage the skin directly, so it can happen to anyone at first exposure.",
   UL("The burn has **bizarre, geometric shapes** (streaks, drips, splashes, finger- and hand-prints) that trace where the juice or sap touched.",
      "It heals with **brown pigmentation** that can persist for months.",
      "Classic UK sources: **giant hogweed**, wild parsnip and rue (strimming, walking), and **limes** (cocktails and cooking on holiday).",
      "**Berloque dermatitis** is a variant from bergamot-containing perfume on the neck.")),
 S('epidemiology', 'Epidemiology',
   UL(N("**Who**", "Any age, sex or skin type; incidence is unknown because mild cases are not reported."),
      N("**When**", "Mostly **summer** and sunny holidays, when people handle plants or citrus outdoors."),
      N("**At-risk groups**", "Gardeners, farm and grounds workers, bartenders and chefs (limes), children playing outdoors, hikers.", "Fair skin may burn more readily, while darker skin shows more marked and longer-lasting pigmentation."))),
 S('aetiology', ('Aetiology: causes and risk factors', 'Aetiology'),
   "Two things are needed: a **furocoumarin on the skin** and enough **UVA**. Moisture (sweat, water) and heat increase absorption and the reaction.",
   H('Common plant sources'),
   TABLE(["Family", "Examples"],
         ["Apiaceae (Umbelliferae)", "**Giant hogweed**, cow parsley, wild and cultivated **parsnip**, celery, carrot, fennel, dill, parsley"],
         ["Rutaceae", "**Lime**, lemon, bergamot orange, bitter orange, grapefruit, **rue**"],
         ["Moraceae", "**Fig** (leaves and sap)"],
         ["Other", "Some St John's wort and other garden plants"]),
   UL("**Activities**: strimming or mowing weeds, clearing riverbanks, picking wild plants, squeezing limes or making drinks in the sun.",
      "**Berloque dermatitis**: perfume containing bergamot oil (5-methoxypsoralen) applied to the neck, then sun."),
   H('Myths to address'),
   UL("**\"It must be an allergy\"**: no; phototoxicity needs no sensitisation and anyone can react.",
      "**\"It was a sunburn\"**: plain sunburn is uniform over exposed skin; the streaks and drips point to a plant or citrus.",
      "**\"The marks are bruises or scars\"**: they are pigment and fade slowly without scarring.")),
 S('pathophysiology', ('Pathophysiology and pathology', 'Pathophysiology'),
   MECH(("Sap meets light", "Furocoumarins in plant sap or citrus juice penetrate the epidermis. **UVA (320–400 nm, peak effect around 335 nm)** activates them; a cloudy day still delivers enough UVA.", "v4-ppd-sap-sun.jpg", "Step 1: furocoumarin-rich sap (e.g. hogweed) on skin, then UVA exposure."),
        ("Phototoxic damage to DNA and membranes", "Activated psoralens act in two ways: **type I** reactions bind directly to **DNA**, forming cross-links between strands; **type II** reactions generate reactive oxygen species that damage cell membranes. No immune memory is involved.", "v4-ppd-dna-crosslink.jpg", "Step 2: UVA-activated psoralen molecules slot between DNA strands and cross-link them."),
        ("Keratinocyte death and blistering", "Damaged keratinocytes die (\"sunburn cells\"), with dermal oedema and inflammation. Severe damage separates the epidermis, producing **vesicles and bullae** after about 24 h, peaking at 48–72 h.", "v4-ppd-blister.jpg", "Step 3: necrotic keratinocytes and an intraepidermal blister above an inflamed dermis."),
        ("Pigment follows", "Psoralen–UVA stimulates **melanocytes** to make more melanin and melanin drops into the dermis where **melanophages** hold it, so brown or grey-brown pigment appears 1–2 weeks later and lasts months.", "v4-ppd-pigment.jpg", "Step 4: active melanocytes and pigment-laden melanophages in the upper dermis cause the long-lasting brown marks.")),
   FIG(AI("v4-ppd-patterns.jpg", "The shape gives it away: drips, streaks and hand-prints that follow where juice or sap touched the skin.", "Limbs and hand with streaky and hand-print burns")),
   HISTO("Acute: necrotic keratinocytes, spongiosis, intraepidermal or subepidermal **vesicles**, dermal oedema and a mild perivascular infiltrate (like an acute sunburn).",
         "Late: **pigment incontinence** with melanophages in the upper dermis and increased basal melanin.",
         "Biopsy is rarely needed; history and shape are diagnostic.")),
 S('clinical-features', 'Clinical features',
   H('Symptoms'),
   UL("**Burning or stinging pain** more than itch, starting about 24 h after sun exposure.",
      "Usually no systemic symptoms, except with extensive hogweed burns.",
      "Later, **brown marks** with no memory of the inflammatory phase: often the presenting complaint."),
   H('Lesions and morphology'),
   LES(("Streaky erythema", "Sharply outlined **linear streaks** of redness and oedema where sap brushed the skin.", "m6w3:N01"),
       ("Vesicles and bullae", "Tense blisters, sometimes large, resembling a partial-thickness burn.", "m6w3:N03"),
       ("Drips and hand-prints", "Drip, splash and finger-print shapes from citrus juice.", "m6w3:N04"),
       ("Hyperpigmentation", "Brown to grey-brown streaks that persist for months after the burn settles.", "m6w3:N05")),
   H('Distribution'),
   UL("**Exposed skin** that touched the plant or juice: hands, forearms, legs and ankles (strimming), around the mouth and chin (citrus), neck (perfume).",
      "Shapes follow contact, **not** the whole sun-exposed area (unlike drug photosensitivity)."),
   {"figs": [{"dermnet": "m6w3:N02", "caption": "Linear redness and blisters after strimming."}, {"dermnet": "m5w6:E02", "caption": "Streaks where juice brushed the skin: an outside cause."}]},
   H('Variants'),
   VAR(("Lime (\"margarita\") dermatitis", "Drips and hand-prints on hands, wrists, face and chest after squeezing limes in the sun.", "m5w6:E01"),
       ("Giant hogweed burn", "Severe blistering on arms and legs after contact with sap on riverbanks and verges; can need burns care.", "m5w6:E04", {"danger": True}),
       ("Bullous phytophotodermatitis", "Large blisters, usually on the lower legs and ankles.", "m5w6:E03"),
       ("Pigmentation-only presentation", "Streaky brown marks without remembered redness.", "m6w3:N06"),
       ("Berloque dermatitis", "Pendant-shaped streaks on the neck from bergamot perfume plus sun.", None)),
   H('Special groups'),
   UL(N("**Children**", "Hand-print or splash patterns can look like **bruising or non-accidental injury**; take a careful plant and sun history and follow safeguarding procedures if the story does not fit."),
      N("**Skin of colour**", "Redness may be subtle; the **hyperpigmentation** is often marked and lasts longer.")),
   {"figs": [{"dermnet": "m5w6:E05", "caption": "Residual pigmentation for months; atypical patterns in children need a careful history."}]}),
 S('diagnosis', ('Diagnosis and investigations', 'Diagnosis'),
   "Diagnosis is **clinical**, from the **bizarre shape** plus an **exposure history**.",
   H('History'),
   UL("Plants handled, strimming or gardening, walks through long vegetation, citrus drinks or cooking, perfumes.",
      "Sun exposure in the previous 1–2 days; timing of symptoms.",
      "Drugs (to exclude drug photosensitivity); previous similar episodes."),
   H('Examination'),
   UL("Shape and site of lesions; blister size and extent; eye involvement; signs of infection."),
   H('Investigations'),
   UL("**Usually none.**", "Swab if secondary infection is suspected.", "Patch or photopatch testing only if allergic contact dermatitis is a possibility.", "Biopsy rarely.")),
 S('differentials', ('Differential diagnoses', 'Differentials'),
   DDX(("Allergic contact dermatitis (plants)", "Very **itchy** eczema; needs sensitisation; does not need sun; spreads beyond the contact.", "contact-dermatitis"),
       ("Drug photosensitivity", "**Uniform** redness over all sun-exposed skin with a drug history (e.g. doxycycline, thiazides).", "drug-photosensitivity"),
       ("Sunburn", "Uniform over exposed sites; no streaks.", None),
       ("Blister beetle dermatitis", "Linear blisters after crushing a beetle; no sun needed.", "blister-beetle-dermatitis"),
       ("Polymorphic light eruption", "Itchy papules on sun-exposed skin hours after sun; recurrent each spring.", "polymorphic-light-eruption"),
       ("!Non-accidental injury", "Inconsistent or changing history, injuries in unusual places, other concerns: **safeguarding** assessment.", None),
       ("Burns or artefact", "History of thermal or chemical injury; patterns may be self-inflicted.", None),
       ("Fixed drug eruption", "Round dusky patches that recur at the same site with each dose.", "fixed-drug-eruption"))),
 S('management', 'Management',
   H('Principles'),
   UL("Treat the acute phase like a **superficial burn**; then protect the pigmented skin from the sun.",
      "Explain the cause so the patient can avoid it; most cases settle without scarring."),
   H('Immediate care after contact (e.g. hogweed sap)'),
   UL("**Wash off sap promptly with soap and water**, cover the skin and keep it **out of sunlight for at least 48 h**.",
      "If sap gets in the eyes: rinse and seek **urgent eye assessment**."),
   H('Conservative and self-care'),
   UL("Cool compresses, emollients and simple analgesia.",
      "Leave blisters intact or use non-adherent dressings; keep clean (topical antiseptic only if needed).",
      "**OTC hydrocortisone 1%** for mild small areas (not on broken skin)."),
   H('Medical treatment'),
   DRUGS(D("Potent topical corticosteroid", cls="Short course", dose="Short course of **5–7 days** to inflamed **intact** skin on the limbs or trunk; **moderate** potency on the face.", cautions="Not on broken or infected skin.", counsel="Apply thinly; stop when redness settles."),
         D("Oral antihistamine", cls="Symptom relief", use="If itchy."),
         D("Secondary infection", cls="Antibiotic per NICE guidance", use="Infected blisters: treat per NICE impetigo / secondary bacterial infection guidance.", counsel="Link: [impetigo](condition:impetigo).")),
   H('Pigmentation phase'),
   UL("Reassure: it **fades slowly over months**.",
      "**Strict sun protection** (even limited UV can darken it again): clothing, broad-spectrum high-SPF sunscreen.",
      "Avoid bleaching agents unless advised by a specialist."),
   H('Prevention'),
   UL("Learn to recognise **giant hogweed**; wear long sleeves, trousers and gloves when strimming or clearing plants.",
      "Wash skin after gardening; avoid squeezing limes or applying citrus or perfume to skin before sun."),
   H('Treatment ladder'),
   LAD(("Everyone", "Wash off sap, 48 h out of sun, cool compresses, analgesia, emollient.", "base"),
       ("Inflamed intact skin", "Potent topical steroid 5–7 days (moderate on face); antihistamine if itchy.", "first"),
       ("Pigmentation", "Reassurance and strict sun protection for months.", "second"),
       ("Burns-level injury", "Large or blistering burns, face, genitals or hands: same-day urgent care or burns unit.", "refer")),
   H('Referral'),
   REF(("same-day", "Large or extensive blistering, burns on the **face, genitals or hands**, severe pain or infection: same-day GP, urgent care or **burns unit**."),
       ("same-day", "Sap in the eye: urgent eye assessment."),
       ("urgent", "**Safeguarding** concern in a child: follow local procedures."),
       ("routine", "Diagnostic doubt or persistent distressing pigmentation."))),
 S('red-flags', ('Red flags and when to refer', 'Red flags'),
   REF(("same-day", "Extensive hogweed burns, eye exposure, or blistering of the face, hands or genitals."),
       ("urgent", "Unexplained marks in a child where the history does not fit: safeguarding."),
       ("routine", "Signs of infection: spreading redness, pus, fever."))),
 S('complications', ('Complications and prognosis', 'Complications'),
   UL("**Post-inflammatory hyperpigmentation** for months, sometimes years.", "Secondary bacterial infection of blisters.", "Rarely scarring after severe bullous burns.", "Misdiagnosis as abuse or burns causing distress."),
   H('Prognosis'),
   UL("The acute reaction settles in 1–2 weeks; pigment fades gradually over months with sun protection.", "Recurs only with re-exposure.")),
 S('pearls', ('Prescriber pearls (UK pharmacist IP)', 'Pearls'),
   PEARLS("Pigmentation, not the acute burn, is often why patients attend.",
          "Berloque = perfume + sun streaks.",
          "Tell gardeners about **giant hogweed**: sap plus sun is a classic UK summer presentation.",
          "Ask about holidays, cocktails and cooking with limes.",
          "Check for photosensitising drugs before blaming the plant.",
          "Other light-related rashes: [polymorphic light eruption](condition:polymorphic-light-eruption), [drug-induced photosensitivity](condition:drug-photosensitivity) and [chronic actinic dermatitis](condition:chronic-actinic-dermatitis).")),
 ],
 [("What two things cause phytophotodermatitis?", "Plant furocoumarins (psoralens) on the skin plus UVA light."),
  ("Is it allergic?", "No: it is phototoxic and needs no previous sensitisation."),
  ("When does it appear and peak?", "About 24 h after exposure, peaking at 48–72 h."),
  ("What clue separates it from drug photosensitivity?", "Bizarre streaks, drips and hand-prints that follow contact, not uniform sun-exposed redness."),
  ("Immediate advice after hogweed sap contact?", "Wash with soap and water, cover and keep out of sunlight for at least 48 h."),
  ("Why mention safeguarding?", "Hand-prints and splashes in children can mimic non-accidental injury.")],
 refs=[("DermNet: Phytophotodermatitis", "https://dermnetnz.org/topics/phytophotodermatitis"),
       ("Medscape: Phytophotodermatitis", "https://emedicine.medscape.com/article/1119566-overview")],
 see_also=["cutaneous-amyloidosis", "drug-photosensitivity", "polymorphic-light-eruption", "blister-beetle-dermatitis"])
